/* MODULE in02 · Bước 9 Rút insight · Case thương hiệu Việt
   10 bài × 7 câu. Mỗi bài đọc một case thương hiệu Việt nổi tiếng CHỈ dựa trên điều ai cũng thấy công khai.
   Không dùng số liệu nội bộ; mọi con số là MINH HOẠ ("giả sử") và tự khớp nhau. */
BAI_ADD({ mod:'in02', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:in02-01', skill:'insight', read:'7 phút', t:'Highlands Coffee bán cà phê hay bán chỗ ngồi?',
  situation:'Bạn ghé một quán Highlands Coffee ở góc ngã tư lúc 3 giờ chiều. Quán rộng, nhiều bàn, có ổ cắm, máy lạnh, một nhóm sinh viên làm bài, hai người đang họp với khách, vài người ngồi một mình với laptop. Ly cà phê trên bàn đã cạn từ lâu. Sếp bạn hỏi: "Theo em, khách trả tiền cho cái gì?"',
  concept:{ name:'Sản phẩm thật là việc khách cần làm',
    body:'Khách không chỉ mua một ly đồ uống; họ "thuê" quán để làm một việc: có chỗ gặp đối tác, chỗ học, chỗ ngồi mát giữa buổi chiều. Ly cà phê là tấm vé vào cửa. Khi đọc một case, hãy hỏi: <b>ngoài thứ được in trên menu, khách thực sự trả tiền cho điều gì?</b> Ở Highlands, những điều ai cũng thấy — mặt bằng rộng ở vị trí dễ thấy, trong trung tâm thương mại và toà nhà văn phòng, bàn ghế cho nhóm — theo cách đọc của bài, đều phục vụ "chỗ ngồi" không kém gì "đồ uống".' },
  example:'Giả sử một quán có 60 ghế, mỗi ngày trung bình mỗi ghế đón 4 lượt khách, mỗi lượt chi 50.000đ → doanh thu ngày 60 × 4 × 50.000 = 12 triệu. Nếu quán chỉ nghĩ mình bán cà phê, họ sẽ coi ghế là thứ để cắt bớt. Nếu hiểu mình bán chỗ ngồi, họ giữ ghế, thêm ổ cắm, và tìm cách tăng lượt ngồi vào giờ vắng — ví dụ combo buổi sáng cho dân văn phòng.',
  takeaway:'Hỏi khách "thuê" sản phẩm để làm việc gì — câu trả lời thường nằm ngoài menu.',
  apply:'Chọn một chuỗi đồ uống bạn hay ghé. Nói trong 60 giây: khách ở đó đang "thuê" quán để làm việc gì, và quán đã làm gì cho thấy họ hiểu điều đó.',
  mistakes:['So sánh quán chỉ bằng giá ly cà phê mà bỏ qua chỗ ngồi và vị trí.','Coi khách ngồi lâu là gánh nặng thay vì là lý do khách chọn quán.'],
  q:[
  { type:'mcq', stem:'Đoán trước: điều gì giải thích tốt nhất vì sao nhiều người chọn ngồi Highlands để họp với khách?',
    options:[{k:'a',t:'Cà phê ở đây là loại rẻ nhất trong khu vực'},{k:'b',t:'Không gian rộng, dễ tìm, lịch sự để gặp người lạ'},
             {k:'c',t:'Quán có thực đơn đồ ăn nhiều món nhất'},{k:'d',t:'Nhân viên được huấn luyện pha chế lâu năm'}],
    answer:'b', why:{a:'Người đi họp ít khi chọn quán vì rẻ nhất; họ cần chỗ phù hợp để gặp khách.',
      b:'Đúng. Việc cần làm là "có chỗ gặp đàng hoàng"; không gian và vị trí phục vụ đúng việc đó.',
      c:'Buổi họp cần chỗ ngồi hơn là nhiều món ăn.',
      d:'Tay nghề pha chế quan trọng với vị, nhưng không phải lý do chính để chọn nơi họp.'} },
  { type:'mcq', stem:'Bạn là brand manager một chuỗi cà phê. Quán ở toà văn phòng vắng từ 14h–17h. Bạn chọn làm gì trước?',
    options:[{k:'a',t:'Giảm bớt số ghế để tiết kiệm tiền thuê mặt bằng, vì giờ vắng thì ghế trống cũng chẳng để làm gì'},{k:'b',t:'Tăng giá đồ uống giờ vắng để bù doanh thu bị hụt'},
             {k:'c',t:'Tìm việc khách văn phòng cần làm lúc chiều, như họp nhanh, rồi mời họ đến'},{k:'d',t:'Chạy quảng cáo đại trà toàn thành phố về món mới'}],
    answer:'c', why:{a:'Bớt ghế chỉ tiết kiệm được nếu thu hẹp diện tích thuê; giữ nguyên hợp đồng thì chi phí vẫn đó mà mất chỗ giờ cao điểm.',
      b:'Giờ vắng mà tăng giá thì càng ít lý do để khách đến.',
      c:'Đúng. Bắt đầu từ việc khách cần làm vào khung giờ đó, rồi thiết kế lời mời (ưu đãi họp nhóm, combo chiều).',
      d:'Vấn đề là một khung giờ ở một quán; quảng cáo cả thành phố quá rộng và tốn kém.'} },
  { type:'calc', stem:'Giả sử một quán có 50 ghế, mỗi ghế đón trung bình 3 lượt khách/ngày, mỗi lượt chi 60.000đ. Doanh thu một ngày là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:9, tol:0.01, wrong:[[3,'SAI_TINH_TOAN'],[0.18,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Số lượt khách = 50 ghế × 3 lượt = 150 lượt.','Doanh thu = 150 × 60.000đ = 9.000.000đ = <b>9 triệu đồng</b>.'] },
  { type:'mcq', stem:'Giả sử quán trên tăng lượt ngồi mỗi ghế từ 3 lên 3,5 nhờ combo buổi chiều. Nhận định nào đúng nhất?',
    options:[{k:'a',t:'Tăng khoảng 17% trên cùng số ghế, không cần mở thêm quán'},{k:'b',t:'Tăng đúng 0,5% vì chỉ thêm nửa lượt khách'},
             {k:'c',t:'Không đổi vì khách giờ chiều thường chi ít hơn nhiều'},{k:'d',t:'Chỉ tăng được khi mở thêm quán mới ở khu vực khác'}],
    answer:'a', why:{a:'Đúng. 3,5 ÷ 3 ≈ 1,17 → tăng khoảng 17% trên cùng số ghế, cùng tiền thuê.',
      b:'Nửa lượt trên nền 3 lượt là tăng khoảng 17%, không phải 0,5%.',
      c:'Có thể chi ít hơn một chút, nhưng đề không cho dữ kiện đó; khẳng định "không đổi" là suy diễn.',
      d:'Tăng lượt ngồi trên ghế sẵn có là cách tăng doanh thu mà không cần mở quán.'} },
  { type:'mcq', stem:'Một chuỗi cà phê mang đi (không có ghế) mở cạnh quán Highlands, bán ly rẻ hơn. Sếp lo mất khách. Trước khi tính cách đối phó, bạn kiểm điều gì trước?',
    options:[{k:'a',t:'So giá ly của hai bên để biết chuỗi mới rẻ hơn bao nhiêu phần trăm mỗi ly'},{k:'b',t:'Khảo sát độ nhận biết logo của chuỗi mới trong khu vực quanh quán Highlands'},
             {k:'c',t:'Tìm số liệu doanh thu quý trước của chuỗi mới để biết nó mạnh đến mức nào'},{k:'d',t:'Đếm tỉ lệ khách mang đi so với khách ngồi lại, vì nhóm mang đi dễ bị lấy mất nhất'}],
    answer:'d', why:{a:'Chênh giá chỉ có nghĩa với nhóm khách mua vì giá; chưa biết nhóm đó chiếm bao nhiêu thì con số chênh chưa dẫn tới quyết định nào.',
      b:'Nhận biết logo cho biết đối thủ có được thấy hay không, không cho biết khách nào của quán có lý do rời đi.',
      c:'Doanh thu nội bộ của đối thủ bạn không có; và dù có, sức mạnh chung của họ không trả lời khách của mình bị ảnh hưởng ra sao.',
      d:'Đúng. Hai bên bán hai việc khác nhau (chỗ ngồi và sự nhanh gọn), nên mức đụng độ phụ thuộc vào nhóm khách mang đi của quán. Đếm nhóm này trước khi hành động.'} },
  { type:'mcq', stem:'Nguyên lý nào rút ra từ case Highlands có thể áp dụng cho một phòng gym?',
    options:[{k:'a',t:'Hãy bán gói tập rẻ hơn đối thủ gần nhất để hút khách'},{k:'b',t:'Hỏi hội viên đến gym để làm việc gì ngoài tập, như gặp bạn, thư giãn sau giờ làm'},
             {k:'c',t:'Mở gym trong trung tâm thương mại vì Highlands cũng làm vậy'},{k:'d',t:'Tăng số máy tập càng nhiều càng tốt để hơn hẳn các phòng khác trong khu, vì khách đến là để tập'}],
    answer:'b', why:{a:'Giá là một yếu tố, nhưng không phải bài học của case về "việc cần làm".',
      b:'Đúng. Nguyên lý là tìm việc khách thật sự thuê sản phẩm để làm, không phải chép vị trí.',
      c:'Chép chiến thuật bề mặt mà không hiểu lý do là lỗi hay gặp khi học case.',
      d:'Nhiều máy chỉ phục vụ việc "tập"; có thể bỏ lỡ lý do khác khiến khách ở lại.'} },
  { type:'mcq', stem:'Khi phân tích case, bạn viết: "Highlands thành công vì cà phê ngon." Góp ý nào hữu ích nhất?',
    options:[{k:'a',t:'Đúng rồi, chất lượng sản phẩm là lý do chính để khách quay lại quán'},{k:'b',t:'Nên thêm số liệu doanh thu nội bộ để lập luận thuyết phục hơn'},
             {k:'c',t:'Câu này khó kiểm chứng; hãy tìm dấu hiệu quan sát được như vị trí, chỗ ngồi'},{k:'d',t:'Nên so với cà phê nước ngoài để thấy ai ngon hơn'}],
    answer:'c', why:{a:'Vị ngon là cảm nhận, khó kiểm chứng và không giải thích được vì sao khách ngồi lâu.',
      b:'Số liệu nội bộ bạn không có; bịa ra thì phân tích mất giá trị.',
      c:'Đúng. Phân tích case tốt dựa trên dữ kiện quan sát được, không dựa vào cảm tính.',
      d:'So vị ngon vẫn là cảm tính và lạc khỏi câu hỏi "khách trả tiền cho gì".'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:in02-02', skill:'insight', read:'7 phút', t:'Vì sao "Đi để trở về" giúp Biti\'s Hunter trẻ lại?',
  situation:'Biti\'s là thương hiệu giày dép quen thuộc với nhiều thế hệ người Việt, nhưng với người trẻ, cái tên có lúc gắn với "giày của bố mẹ". Dòng Biti\'s Hunter được giới thiệu cùng các MV âm nhạc hợp tác với ca sĩ trẻ, nổi bật là chủ đề "Đi để trở về" về hành trình của người trẻ xa nhà và chuyến về quê dịp Tết. Bạn được giao rút ra bài học từ case này.',
  concept:{ name:'Gắn sản phẩm vào một sự thật văn hoá',
    body:'Thay vì nói "giày êm, bền", câu chuyện chạm vào một <b>sự thật văn hoá</b>: một trải nghiệm đủ phổ biến để người trong cuộc nhận ra ngay là của mình, như đi học, đi làm xa và mong ngày về nhà dịp Tết. Đôi giày trở thành <b>vật đi cùng hành trình</b>; người xem tự kể tiếp và thương hiệu cũ có cơ hội được nhìn bằng mắt mới. Giới hạn: sản phẩm phải có vai trò thật trong câu chuyện, và một MV lẻ hiếm khi đủ. Chuỗi "Đi để trở về" do Soobin Hoàng Sơn thể hiện bắt đầu từ Tết 2017 rồi được kể tiếp qua nhiều phần. Âm nhạc là định dạng người trẻ chủ động tìm xem, không phải quảng cáo bị ép nghe.' },
  example:'Đừng đo case này chỉ bằng lượt xem. Giả sử bạn không có số bán hàng nội bộ và phải biết thương hiệu đã "trẻ lại" chưa. Hãy kiểm hai dấu hiệu công khai: (1) bình luận dưới MV nói về quê, về Tết, hay chỉ khen ca sĩ; (2) khi người trẻ cần mua giày, họ có chủ động gõ tên thương hiệu không (so lượt tìm tên hãng trước và sau chiến dịch). Phản ví dụ: một MV 12 triệu lượt xem mà bình luận chỉ khen giọng ca sĩ, lượt tìm tên hãng không đổi, thì đó là MV hay chứ chưa phải thương hiệu trẻ lại. Chi phí mỗi lượt xem rẻ chỉ có nghĩa khi lượt xem dẫn tới nhớ và tìm thương hiệu.',
  takeaway:'Thương hiệu cũ trẻ lại khi gắn vào một sự thật người trẻ đang sống, không phải khi đổi logo.',
  apply:'Chọn một thương hiệu lâu năm bạn biết. Trong 60 giây, nêu một sự thật văn hoá của người trẻ mà thương hiệu đó có thể gắn vào một cách tự nhiên.',
  mistakes:['Kết luận "cứ làm MV với ca sĩ nổi tiếng là thành công", bỏ qua câu chuyện bên trong.','Nghĩ làm trẻ hoá là đổi logo, đổi màu, mà không đổi điều thương hiệu nói.'],
  q:[
  { type:'mcq', stem:'Đoán trước: yếu tố nào có khả năng làm câu chuyện "Đi để trở về" chạm đến người xem nhất?',
    options:[{k:'a',t:'Nó kể một trải nghiệm thật của người trẻ xa nhà mong ngày về Tết'},{k:'b',t:'Nó liệt kê đầy đủ tính năng kỹ thuật của đôi giày như đế êm, nhẹ và bền'},
             {k:'c',t:'Nó có mức giảm giá sâu dành cho người xem MV'},{k:'d',t:'Nó dùng ngôn ngữ tiếng Anh cho sang'}],
    answer:'a', why:{a:'Đúng. Sự thật văn hoá chung khiến người xem thấy mình trong câu chuyện.',
      b:'Tính năng quan trọng khi so sánh, nhưng không tạo cảm xúc để chia sẻ.',
      c:'Case được biết đến vì câu chuyện, không phải vì khuyến mãi.',
      d:'Ngôn ngữ ngoại không phải lý do; chính chủ đề rất Việt mới là điểm mạnh.'} },
  { type:'mcq', stem:'Bạn là brand manager của một hãng nước mắm lâu năm, bị người trẻ xem là "đồ của mẹ". Bạn chọn hướng nào trước?',
    options:[{k:'a',t:'Đổi logo sang phong cách tối giản cho giống thương hiệu công nghệ'},{k:'b',t:'Thuê ngay ca sĩ hot nhất hát một bài có nhắc tên thương hiệu'},
             {k:'c',t:'Giảm giá mạnh cho khách dưới 25 tuổi trong suốt ba tháng liền'},{k:'d',t:'Tìm một sự thật của người trẻ, như tự nấu bữa đầu tiên khi ra ở riêng'}],
    answer:'d', why:{a:'Đổi hình thức mà không đổi điều nói thì người trẻ vẫn chưa có lý do để quan tâm.',
      b:'Người nổi tiếng mà không có câu chuyện thì chỉ mua được sự chú ý ngắn hạn.',
      c:'Giảm giá kéo doanh số tạm thời, không thay đổi cách người trẻ nhìn thương hiệu.',
      d:'Đúng. Như case Biti\'s Hunter: bắt đầu từ một khoảnh khắc thật mà thương hiệu có vai trò tự nhiên.'} },
  { type:'calc', stem:'Giả sử (số minh hoạ) MV tốn 800 triệu sản xuất và 1,2 tỉ phân phối. Trước chiến dịch, mỗi tháng có 20.000 lượt tìm tên thương hiệu; trong 3 tháng chiến dịch, trung bình 50.000 lượt mỗi tháng. Chi phí cho mỗi lượt tìm tên tăng thêm là bao nhiêu nghìn đồng? (làm tròn 1 chữ số thập phân)',
    unit:'nghìn đồng', ans:22.2, tol:0.1, wrong:[[13.3,'SAI_MAU_SO'],[66.7,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Tổng chi phí = 800 + 1.200 = 2.000 triệu đồng.','Lượt tìm tăng thêm mỗi tháng = 50.000 − 20.000 = 30.000; trong 3 tháng = 90.000 lượt.','Chi phí mỗi lượt tăng thêm = 2.000.000.000 ÷ 90.000 ≈ <b>22,2 nghìn đồng</b>.','Chia cho 150.000 (13,3) là tính cả lượt tìm vốn đã có; chia cho 30.000 (66,7) là quên nhân 3 tháng.'] },
  { type:'mcq', stem:'Một đồng nghiệp tóm tắt case: "Bài học là cứ làm MV ca nhạc." Góp ý nào đúng nhất?',
    options:[{k:'a',t:'Đúng, MV ca nhạc rẻ hơn quảng cáo truyền hình và dễ lan truyền hơn'},{k:'b',t:'MV chỉ là định dạng; điều cốt lõi là sự thật văn hoá mà câu chuyện chạm vào'},
             {k:'c',t:'Sai, vì MV ca nhạc chỉ hợp với thương hiệu thời trang, không hợp ngành khác'},{k:'d',t:'Đúng, nhưng phải chọn ca sĩ có nhiều người theo dõi nhất thị trường'}],
    answer:'b', why:{a:'MV không chắc rẻ hơn hay lan truyền hơn; nhiều MV quảng cáo không ai xem. Định dạng không phải cốt lõi.',
      b:'Đúng. Chép định dạng mà thiếu sự thật đủ mạnh thì khó lặp lại kết quả.',
      c:'Định dạng âm nhạc được nhiều ngành dùng; vấn đề không nằm ở ngành.',
      d:'Độ nổi tiếng giúp phân phối, không thay được câu chuyện.'} },
  { type:'mcq', stem:'Điều gì cho thấy câu chuyện "về nhà dịp Tết" hợp với một hãng giày hơn là một hãng phần mềm kế toán?',
    options:[{k:'a',t:'Hãng giày có ngân sách quảng cáo lớn hơn hãng phần mềm'},{k:'b',t:'Người trẻ không dùng phần mềm kế toán nên không cần quảng cáo cho họ'},
             {k:'c',t:'Giày đi cùng chuyến đi theo nghĩa đen, nên vai trò của sản phẩm trong câu chuyện tự nhiên'},{k:'d',t:'Tết là mùa mua sắm lớn nhất năm, nên thương hiệu thuộc ngành nào cũng nên kể chuyện về quê'}],
    answer:'c', why:{a:'Ngân sách không quyết định câu chuyện có khớp với sản phẩm hay không.',
      b:'Người trẻ vẫn có thể dùng phần mềm; vấn đề là vai trò sản phẩm trong câu chuyện.',
      c:'Đúng. Sự thật văn hoá phải có chỗ tự nhiên cho sản phẩm, nếu không sẽ gượng ép.',
      d:'Kể chuyện về quê khi sản phẩm không liên quan dễ bị xem là "đu trend Tết".'} },
  { type:'mcq', stem:'Hai MV cùng ngân sách. MV A: 12 triệu lượt xem, lượt tìm tên hãng gần như không đổi, bình luận chủ yếu khen ca sĩ. MV B: 3 triệu lượt xem, lượt tìm tên hãng tăng rõ, nhiều bình luận kể chuyện về quê gắn với đôi giày. Mục tiêu là làm thương hiệu trẻ lại. Đánh giá nào hợp lý nhất?',
    options:[{k:'a',t:'MV A thắng vì lượt xem gấp bốn lần MV B với cùng chi phí bỏ ra cho sản xuất'},{k:'b',t:'MV B có dấu hiệu tốt hơn vì người xem nhắc tới hãng và chủ động đi tìm'},
             {k:'c',t:'Chưa so sánh được vì chưa có số doanh thu nội bộ của riêng hai MV này'},{k:'d',t:'Hai MV ngang nhau vì cùng ngân sách và cùng cách phân phối trên mạng'}],
    answer:'b', why:{a:'Lượt xem đo sự chú ý, không đo thương hiệu có được nhớ và tìm tới hay không; MV A xem nhiều mà người xem nhớ ca sĩ, không nhớ hãng.',
      b:'Đúng. Hai dấu hiệu công khai (lượt tìm tên hãng, nội dung bình luận) gần mục tiêu hơn lượt xem; vẫn chưa phải bằng chứng doanh số.',
      c:'Doanh thu là bằng chứng mạnh nhất, nhưng không phải thứ duy nhất; chờ có số nội bộ thì không bao giờ đánh giá được case công khai.',
      d:'Cùng đầu vào không có nghĩa cùng kết quả; chính phần kể chuyện và vai trò sản phẩm tạo khác biệt.'} },
  { type:'mcq', stem:'Tiêu chí nào giúp bạn đánh giá case này thành công mà không cần số liệu nội bộ của hãng?',
    options:[{k:'a',t:'Đoán doanh thu dòng Hunter từ số lượt xem MV'},{k:'b',t:'Hỏi nhân viên bán hàng một cửa hàng xem họ có thích không'},
             {k:'c',t:'Tin rằng MV nhiều lượt xem thì dòng giày đó cũng đã bán được nhiều hơn hẳn trước kia'},{k:'d',t:'Quan sát công khai: câu chuyện được nhắc lại, người trẻ nói về thương hiệu theo cách mới'}],
    answer:'d', why:{a:'Đoán doanh thu từ lượt xem là bịa số; hai thứ không quy đổi trực tiếp.',
      b:'Ý kiến một người là giai thoại, không đủ đại diện.',
      c:'Lượt xem không tự động thành doanh số; đó là suy diễn thiếu căn cứ.',
      d:'Đúng. Khi không có số nội bộ, dùng dấu hiệu công khai quan sát được và nói rõ giới hạn.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:in02-03', skill:'insight', read:'6 phút', t:'Vinamilk dạy gì về chuyện "có mặt ở mọi nơi"?',
  situation:'Bạn đi từ thành phố về một thị trấn ở miền Trung. Ở siêu thị lớn, tạp hoá đầu ngõ, căng tin trường học, bạn đều thấy hộp sữa Vinamilk. Một người bạn làm startup sữa hạt than: "Sản phẩm mình ngon hơn, bao bì đẹp hơn, sao không ai mua?" Bạn muốn dùng case Vinamilk để trả lời.',
  concept:{ name:'Sẵn có trong tâm trí và sẵn có trên kệ',
    body:'Một thương hiệu lớn được chọn nhờ hai thứ: <b>sẵn có trong tâm trí</b> (khi cần mua sữa, tên nó hiện ra đầu tiên) và <b>sẵn có trên kệ</b> (ở đâu cũng mua được); hai khái niệm này được Byron Sharp trình bày trong sách How Brands Grow (2010). Vinamilk là ví dụ quen thuộc: tên tuổi lâu năm và độ phủ rộng từ thành phố tới nông thôn. Sản phẩm ngon hơn chưa đủ nếu khách phải đi tìm. Nhưng phủ kệ không miễn phí: phải trả chiết khấu cho nhà phân phối, xử lý đổi trả và tồn kho, nên hãng nhỏ thường chọn một vùng đủ nhỏ để phủ kín thay vì phủ cả nước.' },
  example:'Giả sử 1.000 người muốn mua sữa trong tuần, 80% đi chợ, tạp hoá gần nhà. Thương hiệu lớn có ở 90% điểm bán đó, startup sữa hạt chỉ ở 5%. Dù 30% người thích thử sữa hạt, số người gặp và mua chỉ khoảng 1.000 × 80% × 5% × 30% = 12 người. Cùng sức hút đó với độ phủ 90% sẽ là 216 người, gấp 18 lần. Nhưng phủ 90% cần nhà phân phối và chiết khấu mà startup chưa gánh nổi, nên bước đầu là chọn một quận và phủ kín ở đó. Vấn đề đầu tiên của startup không phải hương vị mà là không có mặt.',
  takeaway:'Người mua không đi tìm bạn; hãy có mặt ở nơi họ vốn đã mua và trong đầu họ khi cần.',
  apply:'Chọn một quận bạn quen. Trong 60 giây, nói cách bạn đo độ phủ của một hãng sữa ở đó: có hàng ở bao nhiêu điểm bán trên tổng điểm bán sữa, đếm trong 4 tuần.',
  mistakes:['Tin rằng sản phẩm ngon hơn sẽ tự được tìm đến.','Đổ hết ngân sách vào quảng cáo trong khi hàng chưa có trên kệ gần khách.'],
  q:[
  { type:'mcq', stem:'Đoán trước: startup sữa hạt ngon nhưng bán chậm. Nguyên nhân nào đáng kiểm tra đầu tiên?',
    options:[{k:'a',t:'Bao bì chưa đủ đẹp so với các hãng nhập khẩu'},{k:'b',t:'Giá cao hơn hãng lớn vài nghìn đồng mỗi hộp'},
             {k:'c',t:'Khách có gặp được sản phẩm ở nơi họ vẫn mua sữa hằng tuần không'},{k:'d',t:'Công thức cần chỉnh lại vị cho hợp với khẩu vị người mua ở thị trấn đó'}],
    answer:'c', why:{a:'Bao bì chỉ có tác dụng khi khách nhìn thấy nó trên kệ.',
      b:'Giá có thể ảnh hưởng, nhưng khách phải gặp sản phẩm trước mới so giá.',
      c:'Đúng. Không có mặt thì mọi ưu điểm khác không có cơ hội phát huy.',
      d:'Có thể cần chỉnh vị, nhưng chưa ai nếm thì chưa có dữ liệu để chỉnh; kiểm tra việc gặp được sản phẩm trước.'} },
  { type:'mcq', stem:'Bạn là brand manager startup đó, có 500 triệu cho quý tới. Bạn chọn chia ngân sách thế nào?',
    options:[{k:'a',t:'Dồn cả 500 triệu cho quảng cáo mạng xã hội trên toàn quốc để tăng nhận biết'},{k:'b',t:'Ưu tiên phủ kệ ở một vùng nhỏ, rồi quảng cáo đúng vùng đó'},
             {k:'c',t:'Thuê một người nổi tiếng quốc gia quay một video giới thiệu'},{k:'d',t:'Giảm giá 50% trên sàn thương mại điện tử để kéo lượt mua'}],
    answer:'b', why:{a:'Quảng cáo toàn quốc khi hàng chưa có trên kệ: người xem muốn mua cũng không tìm thấy.',
      b:'Đúng. Có mặt thật và được nhắc tới ở cùng một vùng thì mỗi đồng quảng cáo mới dẫn tới đơn hàng.',
      c:'Một video không giải quyết được chuyện khách ra tiệm không thấy hàng.',
      d:'Kéo đơn online ngắn hạn nhưng đốt lãi và không chạm tới đa số người mua ở tạp hoá.'} },
  { type:'calc', stem:'Giả sử 2.000 người mua sữa mỗi tuần ở tạp hoá. Sản phẩm có mặt ở 10% tạp hoá, và 25% người gặp sản phẩm sẽ mua thử. Có bao nhiêu người mua thử?',
    unit:'người', ans:50, tol:0.5, wrong:[[500,'QUEN_TI_LE_CHUYEN_DOI'],[200,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Người gặp sản phẩm = 2.000 × 10% = 200 người.','Người mua thử = 200 × 25% = <b>50 người</b>.','Nếu lấy 2.000 × 25% = 500 là quên rằng chỉ 10% điểm bán có hàng.'] },
  { type:'mcq', stem:'Nếu sản phẩm tăng độ phủ từ 10% lên 30% tạp hoá, số người mua thử (các yếu tố khác giữ nguyên) sẽ thế nào?',
    options:[{k:'a',t:'Tăng thêm khoảng 20% so với trước'},{k:'b',t:'Giữ nguyên, vì người mua đã có thói quen cũ không đổi'},
             {k:'c',t:'Giảm, vì phân phối rộng làm thương hiệu mất độ hiếm'},{k:'d',t:'Tăng gấp ba, vì số người gặp sản phẩm tăng gấp ba'}],
    answer:'d', why:{a:'Nhầm điểm phần trăm (+20 điểm) với phần trăm tăng; 30 ÷ 10 = gấp ba.',
      b:'Có thói quen, nhưng người không gặp sản phẩm thì không có cơ hội thử.',
      c:'Độ hiếm chỉ có giá trị với hàng xa xỉ; sữa hằng ngày cần tiện.',
      d:'Đúng. Số người gặp sản phẩm tăng từ 200 lên 600, số mua thử theo tỉ lệ cũ tăng gấp ba.'} },
  { type:'mcq', stem:'Hai phương án cùng ngân sách. A: phủ 30% tạp hoá cả tỉnh, mỗi điểm chỉ một hộp. B: phủ 60% tạp hoá ở hai quận và nhắc tên ở đúng hai quận đó. Phương án nào giúp biết sớm và chắc hơn rằng sản phẩm có bán được?',
    options:[{k:'a',t:'B, vì phủ dày ở vùng nhỏ cho khách gặp lặp lại và số liệu đọc được'},{k:'b',t:'A, vì phủ cả tỉnh cho nhiều người gặp sản phẩm nhất có thể'},
             {k:'c',t:'A, vì chiết khấu cho mỗi điểm thấp nên rủi ro mất tiền ít hơn'},{k:'d',t:'B, vì hai quận luôn có khách giàu hơn nên bán được giá cao'}],
    answer:'a', why:{a:'Đúng. Dày ở vùng nhỏ thì khách gặp nhiều lần, quảng cáo dẫn đúng nơi có hàng, và bạn đọc được doanh số theo điểm bán.',
      b:'Mỏng khắp tỉnh thì mỗi người gặp ít, còn số liệu rải rác nên khó biết sản phẩm kém do vị hay do ít người thấy.',
      c:'Chiết khấu thấp chỉ là một khoản chi; phủ mỏng không đủ doanh số khiến nhà phân phối không giữ hàng.',
      d:'Giả định về mức giàu của hai quận không có căn cứ trong đề, và không liên quan độ phủ.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng nước tăng lực mới chỉ bán qua website riêng. Lời khuyên nào khớp bài học nhất?',
    options:[{k:'a',t:'Làm website đẹp hơn và thêm chatbot tư vấn để khách tự tìm đến đặt hàng'},{k:'b',t:'Đưa hàng vào cửa hàng tiện lợi, trạm xăng — nơi người cần tỉnh táo đang đứng'},
             {k:'c',t:'Tăng giá để tạo cảm giác cao cấp và độc quyền'},{k:'d',t:'Chờ khách truyền miệng cho nhau rồi mới mở rộng'}],
    answer:'b', why:{a:'Nước tăng lực thường mua ngẫu hứng; ít ai lên website đặt một lon.',
      b:'Đúng. Có mặt ở đúng nơi và lúc nhu cầu phát sinh.',
      c:'Định vị cao cấp không giải quyết được chuyện khách không thấy hàng.',
      d:'Truyền miệng cần người đã dùng; ít người gặp sản phẩm thì truyền miệng rất chậm.'} },
  { type:'mcq', stem:'Khi viết phân tích case Vinamilk, câu nào cần tránh nhất?',
    options:[{k:'a',t:'"Vinamilk có mặt ở rất nhiều loại điểm bán, từ siêu thị tới tạp hoá."'},{k:'b',t:'"Nhiều người Việt quen tên Vinamilk từ nhỏ."'},
             {k:'c',t:'"Bài học: độ phủ giúp khách dễ chọn khi không muốn đi tìm."'},{k:'d',t:'"Vinamilk có đúng 250.000 điểm bán, lợi nhuận mỗi điểm 3 triệu."'}],
    answer:'d', why:{a:'Đây là điều quan sát được công khai.',
      b:'Đây là nhận định phổ biến, hợp lý.',
      c:'Đây là nguyên lý rút ra, không cần số nội bộ.',
      d:'Đúng. Đưa con số cụ thể không có nguồn là bịa dữ liệu — cần tránh.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:in02-04', skill:'brand', read:'6 phút', t:'Khi điện thoại ở đâu cũng giống nhau, Thế Giới Di Động bán gì?',
  situation:'Một chiếc điện thoại cùng mẫu, cùng màu có thể mua ở nhiều nơi: sàn thương mại điện tử, cửa hàng nhỏ, chuỗi lớn. Thế Giới Di Động là chuỗi quen thuộc với cửa hàng ở khắp tỉnh thành, nhân viên đông, có khu trải nghiệm máy và chính sách đổi trả, bảo hành được công bố rõ. Mẹ bạn luôn mua ở đó dù có nơi rẻ hơn một chút.',
  concept:{ name:'Dịch vụ là khác biệt khi hàng hoá giống nhau',
    body:'Khi sản phẩm cốt lõi giống hệt nhau, khách chọn nơi bán dựa trên <b>những gì bao quanh sản phẩm</b>: được cầm thử, được giải thích, được chuyển dữ liệu, biết chỗ bảo hành, yên tâm nếu máy lỗi. Với người không rành công nghệ, rủi ro mua nhầm là nỗi lo lớn hơn vài trăm nghìn chênh giá. Nhưng dịch vụ chỉ bền khi biên đủ trả cho nó: chuỗi lớn còn cạnh tranh bằng giá nhập theo quy mô và trả góp, nên yên tâm là một phần lý do khách quay lại, không phải toàn bộ.' },
  example:'Giả sử một chiếc điện thoại giá 8 triệu ở chuỗi lớn và 7,7 triệu ở nơi khác. Chênh 300.000đ, khoảng 3,9% so với giá nơi rẻ hơn. Với một người lớn tuổi, nếu máy lỗi mà không biết đem đi đâu, họ có thể mất cả tuần và nhiều công sức. Họ sẵn lòng trả 300.000đ để có người cài đặt, dặn dò và chỗ quay lại. Khách trẻ rành máy thì có thể chọn nơi rẻ hơn — hai nhóm, hai lý do.',
  takeaway:'Khi sản phẩm không khác, hãy bán sự yên tâm quanh sản phẩm — và biết nhóm khách nào trả tiền cho nó.',
  apply:'Nghĩ về món đồ công nghệ bạn mua gần nhất. Trong 60 giây, nói: điều gì ngoài giá khiến bạn chọn nơi mua đó.',
  mistakes:['Nghĩ bán lẻ chỉ cạnh tranh bằng giá.','Cho rằng mọi khách đều quan tâm dịch vụ như nhau.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao nhiều người vẫn mua điện thoại ở chuỗi lớn dù có nơi rẻ hơn chút ít?',
    options:[{k:'a',t:'Vì họ không biết có nơi bán rẻ hơn'},{k:'b',t:'Vì chuỗi lớn nhập nhiều nên giá bán rẻ hơn'},
             {k:'c',t:'Vì máy bán ở chuỗi lớn là hàng tuyển chọn, chất lượng tốt hơn máy cùng mẫu ở nơi khác'},{k:'d',t:'Vì họ trả thêm để được hướng dẫn, bảo hành và yên tâm khi máy lỗi'}],
    answer:'d', why:{a:'Đề không nói khách không biết giá nơi khác, nên không có cơ sở để chọn; tình huống chỉ nói họ vẫn chọn dù có nơi rẻ hơn.',
      b:'Tình huống nói rõ có nơi rẻ hơn; khách trả thêm chứ không phải mua được rẻ hơn.',
      c:'Cùng mẫu cùng hãng thì máy như nhau; khác biệt nằm ở dịch vụ.',
      d:'Đúng. Sự yên tâm và hỗ trợ là thứ khách đang trả thêm.'} },
  { type:'mcq', stem:'Bạn là brand manager một chuỗi điện máy nhỏ, không thể rẻ hơn sàn online. Bạn chọn khác biệt ở đâu?',
    options:[{k:'a',t:'Hỗ trợ tận nơi cho người lớn tuổi: cài đặt, chuyển danh bạ, hướng dẫn dùng'},{k:'b',t:'Giảm giá sâu hơn sàn online trong một tháng để giành lại khách hàng'},
             {k:'c',t:'Chạy quảng cáo so sánh giá trực tiếp với các sàn lớn nhất'},{k:'d',t:'Bán thêm thật nhiều mẫu mã hiếm để có hàng mà sàn không có'}],
    answer:'a', why:{a:'Đúng. Chọn một nhóm khách cần dịch vụ và làm thật tốt điều sàn online không làm được.',
      b:'Cuộc đua giá với sàn lớn thường khiến chuỗi nhỏ cạn tiền trước.',
      c:'So giá khi mình không rẻ hơn là tự đưa khách sang đối thủ.',
      d:'Hàng hiếm có thể thu hút một ít người, nhưng tốn vốn tồn kho và khó duy trì.'} },
  { type:'calc', stem:'Giả sử máy giá 8 triệu ở chuỗi lớn và 7,6 triệu ở nơi khác. Khách trả thêm bao nhiêu phần trăm so với giá nơi rẻ hơn? (làm tròn 1 chữ số thập phân)',
    unit:'%', ans:5.3, tol:0.1, wrong:[[5,'SAI_MAU_SO'],[400,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO'],
    steps:['Chênh lệch = 8 − 7,6 = 0,4 triệu.','So với giá nơi rẻ hơn: 0,4 ÷ 7,6 ≈ 0,0526 → <b>khoảng 5,3%</b>.','Chia cho 8 triệu ra 5% là lấy nhầm mẫu số.'] },
  { type:'mcq', stem:'Nhóm khách nào ít có khả năng trả thêm cho dịch vụ nhất?',
    options:[{k:'a',t:'Người lớn tuổi mua chiếc điện thoại thông minh đầu tiên, chưa biết chuyển dữ liệu'},{k:'b',t:'Phụ huynh mua máy cho con vào lớp một, ít thời gian tự tìm hiểu'},
             {k:'c',t:'Người đã dùng đúng dòng máy này nhiều năm, tự chuyển dữ liệu, biết chỗ bảo hành'},{k:'d',t:'Người mua máy làm quà biếu, cần hoá đơn rõ ràng và đổi trả được'}],
    answer:'c', why:{a:'Người mới dùng rất cần hướng dẫn — nhóm trả thêm nhiều nhất.',
      b:'Phụ huynh ít thời gian, muốn được tư vấn máy phù hợp.',
      c:'Đúng. Họ tự lo được phần lớn thứ dịch vụ cung cấp, nên giá là yếu tố chính.',
      d:'Mua quà cần yên tâm về nguồn gốc, đổi trả — dịch vụ vẫn có giá trị.'} },
  { type:'mcq', stem:'Một cửa hàng nhỏ bán máy 8 triệu, bằng giá sàn online, lãi gộp 320.000đ mỗi máy. Họ cam kết cài đặt tận nơi, tốn trung bình 200.000đ mỗi máy. Một nửa số đơn đến từ khách lớn tuổi chỉ mua vì có cài đặt tận nơi. Nhận định nào đúng?',
    options:[{k:'a',t:'Dịch vụ tốt tự kéo đông khách nên không cần tính lãi từng máy nữa'},{k:'b',t:'Còn 120.000đ lãi mỗi máy, cần giới hạn dịch vụ cho nhóm khách cần nó'},
             {k:'c',t:'Nên bỏ dịch vụ và giảm thêm 100.000đ mỗi máy để thắng sàn về giá'},{k:'d',t:'Nên nâng giá cao hơn sàn 20% để bù, vì khách yên tâm sẽ chấp nhận'}],
    answer:'b', why:{a:'Khách đông mà mỗi máy lãi mỏng thì dịch vụ ăn hết lãi; yên tâm là lý do chọn, không phải giấy phép bỏ tính toán.',
      b:'Đúng. Dịch vụ chỉ trả được khi biên đủ; chỉ còn 120.000đ nên phải chọn đúng nhóm khách cần nó hoặc thu một phần phí.',
      c:'Bỏ dịch vụ thì mất nửa số đơn: 100 máy cũ còn 50 máy × 220.000đ = 11 triệu, thấp hơn 100 × 120.000đ = 12 triệu, lại bước vào cuộc đua giá với sàn.',
      d:'Chênh 20% (1,6 triệu) vượt xa mức nhiều khách chịu trả thêm; khách rành máy sẽ sang sàn online.'} },
  { type:'mcq', stem:'Tình huống mới: hai nhà thuốc cạnh nhau bán cùng loại thuốc cùng giá. Nhà thuốc A muốn học case này. A nên làm gì?',
    options:[{k:'a',t:'Hạ giá thấp hơn nhà thuốc B một chút ở các loại thuốc để kéo khách sang'},{k:'b',t:'Treo biển hiệu to hơn, sáng đèn hơn và mở nhạc thật lớn'},
             {k:'c',t:'Nhập thật nhiều loại thực phẩm chức năng để bày kín kệ'},{k:'d',t:'Dược sĩ dặn kỹ cách dùng, ghi chú giờ uống lên hộp cho người già'}],
    answer:'d', why:{a:'Chiến tranh giá giữa hai tiệm sát nhau làm cả hai mỏng lãi.',
      b:'Biển hiệu thu hút ánh nhìn nhưng không tạo lý do để khách quay lại.',
      c:'Nhiều hàng không giải quyết nỗi lo của khách về cách dùng thuốc.',
      d:'Đúng. Dịch vụ quanh sản phẩm giải quyết nỗi lo thật của khách.'} },
  { type:'mcq', stem:'Khi phân tích case một chuỗi bán lẻ, dữ kiện nào bạn dùng được mà không cần hỏi nội bộ?',
    options:[{k:'a',t:'Tỉ suất lợi nhuận của từng cửa hàng trong năm qua, suy ra từ số nhân viên đứng quầy'},{k:'b',t:'Chi phí lương thực tế của nhân viên bán hàng'},
             {k:'c',t:'Chính sách đổi trả, bảo hành được công bố và trải nghiệm khi bạn tự đến cửa hàng'},{k:'d',t:'Số lượng máy bán ra mỗi ngày của từng chi nhánh'}],
    answer:'c', why:{a:'Đây là dữ liệu nội bộ, bạn không có.',
      b:'Dữ liệu nội bộ, không công khai.',
      c:'Đúng. Chính sách công bố và trải nghiệm tự quan sát là dữ kiện hợp lệ.',
      d:'Dữ liệu nội bộ; đoán ra là bịa số.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:in02-05', skill:'brand', read:'6 phút', t:'Phúc Long giữ gì khi mở rộng sang kênh mới?',
  situation:'Phúc Long nổi tiếng với trà và các món đồ uống từ trà; bài này giả định lõi thương hiệu là vị trà đậm (giả định để phân tích, không phải số liệu công bố). Ngoài cửa hàng riêng, thương hiệu xuất hiện dưới dạng quầy nhỏ trong chuỗi cửa hàng bán lẻ và có sản phẩm trà đóng gói. Sếp hỏi bạn: "Mở rộng nhiều kênh như vậy, điều gì phải giữ nguyên để khách vẫn thấy đó là Phúc Long?"',
  concept:{ name:'Giữ lõi khi mở rộng kênh',
    body:'Mỗi thương hiệu có một <b>lõi</b> mà khách gắn với nó — với Phúc Long, theo giả định của bài, đó là trà vị đậm, dễ nhận ra. Khi đi vào kênh mới (quầy nhỏ, hàng đóng gói, giao hàng), hình thức có thể đổi: ít ghế hơn, menu gọn hơn. Cách tìm lõi: xem món nào chiếm phần lớn lượt gọi và khiến khách quay lại. Khi cắt menu, giữ nhóm đó trước, rồi mới đánh đổi tốc độ và biên lãi ở phần còn lại. Nếu lõi bị pha loãng, khách thấy "không còn như trước" ở mọi kênh, kể cả cửa hàng gốc.' },
  example:'Giả sử một quầy nhỏ có menu 15 món thay vì 40 món như cửa hàng lớn. Cách cắt đúng: giữ các món trà đặc trưng khách hay gọi, bỏ các món phụ ít người mua. Cách cắt sai: giữ món dễ pha nhanh nhưng bỏ món trà đặc trưng vì tốn thời gian. Quầy chạy nhanh hơn, nhưng khách đến để uống đúng "vị Phúc Long" thì thất vọng.',
  takeaway:'Mở rộng kênh thì đổi hình thức được, nhưng đừng đổi thứ khiến khách chọn bạn.',
  apply:'Chọn một thương hiệu đồ uống bạn thích. Trong 60 giây, nói: nếu nó mở quầy nhỏ, món nào bắt buộc phải có, món nào bỏ được.',
  mistakes:['Cắt menu theo độ dễ làm thay vì theo lý do khách chọn thương hiệu.','Nghĩ kênh mới chỉ là thêm điểm bán, không ảnh hưởng hình ảnh chung.'],
  q:[
  { type:'mcq', stem:'Đoán trước: khi một chuỗi trà mở quầy nhỏ trong cửa hàng tiện lợi, rủi ro lớn nhất cho thương hiệu là gì?',
    options:[{k:'a',t:'Khách ở cửa hàng tiện lợi chủ yếu mua đồ ăn nhanh, ít có thói quen uống trà pha'},{k:'b',t:'Chất lượng và vị ở quầy nhỏ kém đi, làm khách mất niềm tin vào cả thương hiệu'},
             {k:'c',t:'Quầy nhỏ bán chạy hơn cửa hàng chính nên các cửa hàng gốc bị vắng khách'},{k:'d',t:'Giá thuê mặt bằng quầy nhỏ đắt hơn cửa hàng lớn nên lãi mỗi ly bị ăn mòn'}],
    answer:'b', why:{a:'Không có căn cứ; người đi cửa hàng tiện lợi vẫn mua đồ uống.',
      b:'Đúng. Trải nghiệm kém ở một kênh kéo hình ảnh chung đi xuống.',
      c:'Bán nhiều không phải rủi ro cho thương hiệu.',
      d:'Quầy nhỏ thường tốn ít mặt bằng hơn; đây không phải rủi ro chính.'} },
  { type:'mcq', stem:'Bạn là brand manager, phải rút menu quầy nhỏ từ 40 xuống 15 món. Bạn chọn giữ món theo tiêu chí nào?',
    options:[{k:'a',t:'Giữ những món pha nhanh nhất để giảm thời gian khách chờ'},{k:'b',t:'Giữ những món có biên lãi cao nhất bất kể khách có gọi nhiều hay không'},
             {k:'c',t:'Giữ các món đặc trưng khách gắn với thương hiệu, rồi mới tính món phụ'},{k:'d',t:'Giữ những món đang được quảng cáo trên mạng xã hội tháng này'}],
    answer:'c', why:{a:'Nhanh là cần, nhưng nếu mất món đặc trưng thì khách không còn lý do chọn bạn.',
      b:'Biên lãi cao mà ít người gọi thì không kéo được khách tới quầy.',
      c:'Đúng. Lõi thương hiệu đi trước; tối ưu tốc độ và lãi ở phần còn lại.',
      d:'Món quảng cáo theo tháng thay đổi liên tục, không phải nền của menu cố định.'} },
  { type:'calc', stem:'Giả sử một quầy nhỏ bán 200 ly/ngày; 60% là các món trà đặc trưng. Nếu bỏ các món đặc trưng và mất 70% số khách gọi chúng, quầy mất bao nhiêu ly mỗi ngày?',
    unit:'ly', ans:84, tol:0.5, wrong:[[140,'SAI_TINH_TOAN'],[120,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Ly món đặc trưng = 200 × 60% = 120 ly.','Mất 70% số đó = 120 × 70% = <b>84 ly/ngày</b>.','Lấy 200 × 70% = 140 là áp tỉ lệ mất lên cả những khách không gọi món đặc trưng.'] },
  { type:'mcq', stem:'Giả sử nhiều khách lần đầu biết Phúc Long qua gói trà ở siêu thị. Vì sao sản phẩm này cũng cần giữ "lõi" của thương hiệu?',
    options:[{k:'a',t:'Vì bao bì đóng gói rẻ hơn nên cần bù bằng chất lượng'},{k:'b',t:'Vì siêu thị yêu cầu sản phẩm phải giống cửa hàng gốc'},
             {k:'c',t:'Vì khách siêu thị không ghé cửa hàng gốc nên chất lượng gói trà không ảnh hưởng thương hiệu'},{k:'d',t:'Vì với những người đó, gói trà là ấn tượng đầu tiên và nó theo họ sang các kênh khác'}],
    answer:'d', why:{a:'Chi phí bao bì không liên quan đến việc giữ lõi.',
      b:'Yêu cầu của siêu thị là chuyện hợp đồng, không phải lý do thương hiệu tự cần giữ lõi.',
      c:'Sai: với người chỉ gặp thương hiệu qua gói trà, chính gói đó là toàn bộ ấn tượng, nên chất lượng của nó định hình thương hiệu.',
      d:'Đúng. Mỗi kênh là một điểm chạm; ấn tượng ở một kênh ảnh hưởng tới các kênh còn lại.'} },
  { type:'mcq', stem:'Tình huống mới: một tiệm phở gia truyền nổi tiếng mở chi nhánh bán phở gói ăn liền. Điều gì cần giữ nhất?',
    options:[{k:'a',t:'Hương vị nước dùng đặc trưng mà khách nhớ khi nghĩ đến tiệm'},{k:'b',t:'Kích thước bát giống hệt ở tiệm để khách thấy quen thuộc'},
             {k:'c',t:'Giá bằng giá bát phở ở tiệm để giữ hình ảnh cao cấp'},{k:'d',t:'Bàn ghế và cách bài trí giống tiệm gốc trên hình in bao bì'}],
    answer:'a', why:{a:'Đúng. Vị nước dùng là lý do khách chọn tiệm; mất nó thì phở gói chỉ là một gói mì khác.',
      b:'Kích thước bát là hình thức, không phải lõi.',
      c:'Phở gói là kênh khác, giá khác hợp lý; giữ giá bằng bát phở làm sản phẩm khó bán.',
      d:'Hình ảnh bài trí hỗ trợ nhận diện, nhưng không phải lý do khách chọn.'} },
  { type:'mcq', stem:'Bốn câu sau đều nói về case Phúc Long. Câu nào là suy diễn cần kiểm chứng, chưa phải dữ kiện quan sát được?',
    options:[{k:'a',t:'Quầy nhỏ trong chuỗi bán lẻ giúp nhiều người biết đến thương hiệu hơn'},{k:'b',t:'Thương hiệu bán đồ uống từ trà tại các cửa hàng riêng của mình'},
             {k:'c',t:'Thương hiệu có sản phẩm trà đóng gói mang tên Phúc Long'},{k:'d',t:'Thương hiệu có quầy nhỏ đặt trong chuỗi cửa hàng bán lẻ khác'}],
    answer:'a', why:{a:'Đúng. Bài chỉ cho thấy quầy nhỏ có mặt, chưa cho thấy nó tăng nhận biết. Muốn khẳng định cần số đo, ví dụ tỉ lệ khách quầy nói lần đầu biết thương hiệu ở đó.',
      b:'Đây là dữ kiện quan sát được công khai: cửa hàng riêng bán đồ uống trà.',
      c:'Đây là dữ kiện quan sát được trên kệ hàng, không cần suy diễn.',
      d:'Đây là dữ kiện quan sát được: quầy nhỏ có mặt trong chuỗi bán lẻ.'} },
  { type:'calc', stem:'Giả sử quầy nhỏ chỉ giữ 3 món, trong đó món trà đặc trưng A bắt buộc giữ. Mỗi ngày (ly bán × lãi/ly): A 50 × 12.000đ; B 45 × 6.000đ; C 30 × 20.000đ; D 25 × 16.000đ; E 15 × 25.000đ. Chọn 2 món còn lại sao cho tổng lãi gộp ngày cao nhất. Tổng lãi 3 món là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:1.6, tol:0.01, wrong:[[1.47,'SAI_TINH_TOAN'],[1.575,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Lãi mỗi món/ngày: A 600.000đ; B 270.000đ; C 600.000đ; D 400.000đ; E 375.000đ.','Món A giữ cố định; chọn 2 món còn lại có tổng lãi lớn nhất: C (600.000đ) và D (400.000đ).','Tổng = 600.000 + 600.000 + 400.000 = 1.600.000đ = <b>1,6 triệu đồng</b>.','Chọn theo số ly bán (B, C) cho 1,47 triệu; chọn theo lãi/ly (E, C) cho 1,575 triệu: cả hai đều bỏ qua việc nhân số ly với lãi/ly.'] }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:in02-06', skill:'brand', read:'6 phút', t:'Mixue lan nhanh ở Việt Nam nhờ những gì ai cũng thấy?',
  situation:'Chỉ trong thời gian ngắn, cửa hàng Mixue với biển đỏ và hình người tuyết đội vương miện xuất hiện dày đặc ở nhiều con phố. Kem và trà sữa giá thấp, đoạn nhạc ngắn về "yêu bạn" được phát lặp lại, nhiều người trẻ quay video nhảy theo. Sếp giao bạn tách case này thành các nguyên lý có thể học.',
  concept:{ name:'Bốn mảnh ghép cùng chiều: giá, nhận diện, độ phủ, cung ứng',
    body:'Case này dễ bị tóm gọn thành "rẻ nên đông". Thực ra có bốn mảnh ghép cùng chiều: <b>giá thấp</b> hạ rào cản thử; <b>tài sản nhận diện lặp lại</b> (màu đỏ, người tuyết, đoạn nhạc) giúp nhận ra từ xa; <b>độ phủ dày</b> khiến quán luôn ở gần; và nền móng là <b>nhượng quyền gắn với cung ứng nội bộ</b>: hệ thống tự cung cấp nguyên liệu cho chủ cửa hàng ở quy mô lớn, nên giá thấp và mở nhanh mới khả thi. Cộng lại, chúng tạo vòng lặp: thấy nhiều → nhớ → ghé thử vì rẻ → thấy tiếp. Giới hạn: mở nhanh khó giữ chất lượng đồng đều, và báo chí trong nước đã đưa tin chuỗi đóng bớt cửa hàng kém hiệu quả.' },
  example:'Giả sử một người đi học qua 3 cửa hàng cùng biển đỏ mỗi ngày, mỗi tuần 5 ngày → 15 lần nhìn thấy/tuần. Không cần quảng cáo, thương hiệu đã có 15 lần "nhắc tên". Kết hợp giá thấp, lần thử đầu gần như không có rủi ro. So với một quán trà sữa độc lập chỉ có 1 cửa hàng, người đó thấy 5 lần/tuần và giá gấp đôi — rào cản thử cao hơn nhiều.',
  takeaway:'Tăng trưởng nhanh thường đến từ vài mảnh ghép cùng chiều, không từ một chiêu duy nhất.',
  apply:'Chọn một chuỗi bạn thấy mở rất nhanh gần đây. Trong 60 giây, nêu ba mảnh ghép cùng chiều giúp nó lớn.',
  mistakes:['Tóm case thành một lý do duy nhất ("vì rẻ").','Chép giá thấp mà không có chuỗi cung ứng và quy mô để chịu được.'],
  q:[
  { type:'mcq', stem:'Đoán trước: điều gì giúp người qua đường nhận ra cửa hàng Mixue từ rất xa?',
    options:[{k:'a',t:'Màu đỏ và hình người tuyết lặp lại ở các cửa hàng'},{k:'b',t:'Bảng giá ghi to trước cửa'},
             {k:'c',t:'Nhân viên đứng mời khách trên vỉa hè'},{k:'d',t:'Cửa hàng rộng, cao hơn các quán xung quanh'}],
    answer:'a', why:{a:'Đúng. Tài sản nhận diện nhất quán cho phép nhận ra trước khi đọc được chữ.',
      b:'Bảng giá chỉ đọc được khi đã đến gần.',
      c:'Không phải điều đặc trưng của case.',
      d:'Nhiều cửa hàng khá nhỏ; kích thước không phải điểm nhận diện.'} },
  { type:'mcq', stem:'Bạn là brand manager một chuỗi trà sữa nội địa đang bị cạnh tranh. Bạn chọn học điều gì từ case này?',
    options:[{k:'a',t:'Hạ giá xuống ngang Mixue ngay lập tức dù chi phí nguyên liệu của mình cao hơn'},{k:'b',t:'Mở thật nhiều cửa hàng thật nhanh bằng vốn vay'},
             {k:'c',t:'Chép màu đỏ và làm linh vật giống người tuyết'},{k:'d',t:'Xây một tài sản nhận diện riêng dễ nhớ, lặp lại nhất quán ở các điểm chạm'}],
    answer:'d', why:{a:'Đua giá khi chi phí cao hơn là con đường thua lỗ nhanh.',
      b:'Mở nóng bằng vốn vay khi mô hình chưa chắc là rủi ro lớn.',
      c:'Chép tài sản của người khác khiến khách nhớ tới họ, không phải bạn.',
      d:'Đúng. Nguyên lý nhận diện lặp lại học được mà không cần đua giá.'} },
  { type:'calc', stem:'Giả sử một người đi qua 4 cửa hàng cùng thương hiệu mỗi ngày, 6 ngày/tuần. Trong 4 tuần, người đó thấy thương hiệu bao nhiêu lần?',
    unit:'lần', ans:96, tol:0.5, wrong:[[24,'SAI_TINH_TOAN'],[16,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Mỗi tuần = 4 × 6 = 24 lần.','4 tuần = 24 × 4 = <b>96 lần</b>.'] },
  { type:'mcq', stem:'Vì sao đoạn nhạc ngắn được phát lặp lại lại có giá trị với thương hiệu?',
    options:[{k:'a',t:'Vì nhạc vui làm khách đứng lâu hơn trong quán và gọi thêm món thứ hai trước khi rời đi'},{k:'b',t:'Vì âm thanh là tài sản nhận diện: nghe là nhớ tên, kể cả khi không nhìn thấy'},
             {k:'c',t:'Vì nhạc giúp giảm chi phí thuê nhân viên'},{k:'d',t:'Vì bài hát đoạt giải âm nhạc lớn'}],
    answer:'b', why:{a:'Kem mua mang đi nhanh; giữ khách lâu không phải mục đích.',
      b:'Đúng. Giai điệu dễ thuộc được người trẻ lặp lại, mang tên thương hiệu đi xa hơn cửa hàng.',
      c:'Nhạc không thay được nhân viên.',
      d:'Không có dữ kiện về giải thưởng; lý do là tính dễ nhớ.'} },
  { type:'mcq', stem:'Tình huống mới: một chuỗi bánh mì muốn lớn nhanh. Đề xuất nào khớp nhất với nguyên lý "mảnh ghép cùng chiều"?',
    options:[{k:'a',t:'Chỉ tập trung làm bánh ngon hơn, còn lại để tự nhiên'},{k:'b',t:'Chạy thật nhiều quảng cáo trên mạng cho thật nổi tiếng trong khi chuỗi mới có đúng 2 cửa hàng'},
             {k:'c',t:'Giá dễ thử, xe bánh cùng màu dễ nhận ra, đặt dày ở các cổng trường và khu văn phòng'},{k:'d',t:'Bán thêm cà phê, nước ép, cơm trưa để phục vụ nhiều nhu cầu'}],
    answer:'c', why:{a:'Chất lượng cần nhưng không đủ để lớn nhanh nếu khách không thấy.',
      b:'Quảng cáo mà ít điểm bán thì khách muốn mua cũng khó tìm.',
      c:'Đúng. Ba mảnh ghép giá, nhận diện, độ phủ cùng đẩy một hướng.',
      d:'Thêm quá nhiều món làm loãng nhận diện và phức tạp vận hành.'} },
  { type:'mcq', stem:'Một chuỗi nội địa muốn "học Mixue": mở 20 cửa hàng nhượng quyền trong 6 tháng, mỗi chủ cửa hàng tự mua nguyên liệu từ nhà cung cấp nhỏ riêng. Rủi ro lớn nhất là gì?',
    options:[{k:'a',t:'Giá ly 15.000đ vẫn quá cao so với khách trẻ nên phải hạ thêm mới cạnh tranh được'},{k:'b',t:'Mở 20 cửa hàng trong 6 tháng là quá ít để tạo được cảm giác phủ dày ở thành phố'},
             {k:'c',t:'Các chủ nhượng quyền sẽ đòi đổi logo riêng, làm loãng tài sản nhận diện chung'},{k:'d',t:'Mỗi quán một nguồn hàng: vị và giá vốn lệch nhau, khách gặp thương hiệu không giống nhau'}],
    answer:'d', why:{a:'Chưa có dữ kiện về giá đối thủ; hạ giá khi chưa kiểm soát giá vốn còn nguy hiểm hơn.',
      b:'Số lượng chưa phải vấn đề đầu tiên; mở dày mà mỗi quán một kiểu thì càng thấy nhiều càng nhớ sai.',
      c:'Có thể xảy ra, nhưng là chuyện quản trị thương hiệu, không phải mảnh ghép nền móng bị thiếu.',
      d:'Đúng. Cung ứng và chuẩn hoá chung là thứ giữ giá thấp và trải nghiệm đồng đều khi mở nhanh; thiếu nó thì mảnh ghép nhận diện bị phản tác dụng.'} },
  { type:'mcq', stem:'Rủi ro nào cần cân nhắc nếu một thương hiệu nhỏ chép mô hình giá thấp của case này?',
    options:[{k:'a',t:'Giá thấp cần quy mô lớn và chi phí thấp; thiếu hai thứ đó thì bán càng nhiều càng lỗ'},{k:'b',t:'Khách sẽ nghi ngờ ngay, vì trong mắt người mua giá thấp đồng nghĩa với chất lượng kém'},
             {k:'c',t:'Luật không cho phép bán giá thấp hơn một mức nhất định'},{k:'d',t:'Giá thấp làm cửa hàng quá đông, không phục vụ kịp'}],
    answer:'a', why:{a:'Đúng. Giá thấp là kết quả của một mô hình chi phí, không phải một quyết định đứng riêng.',
      b:'Không có căn cứ chung; case cho thấy khách sẵn lòng thử.',
      c:'Không nên khẳng định nội dung luật cụ thể không có nguồn.',
      d:'Quá đông là "vấn đề tốt", không phải rủi ro chính của thương hiệu nhỏ.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:in02-07', skill:'insight', read:'7 phút', t:'Vì sao Grab và Be không dừng ở gọi xe?',
  situation:'Grab và Be bắt đầu được biết đến với dịch vụ gọi xe. Dần dần, trên cùng một ứng dụng có thêm đặt đồ ăn, giao hàng, đi chợ, thanh toán và nhiều tiện ích khác. Người ta gọi đó là "siêu ứng dụng". Một bạn thực tập hỏi: "Sao không làm mỗi thứ một ứng dụng cho gọn?"',
  concept:{ name:'Mở rộng theo nhu cầu kề và tần suất dùng',
    body:'Gọi xe là nhu cầu xuất hiện vài lần một tuần. Ăn trưa, giao đồ, trả tiền xuất hiện gần như mỗi ngày. Khi thêm các dịch vụ <b>kề</b> với thói quen sẵn có — cùng đội tài xế, cùng tài khoản, cùng ví — ứng dụng được mở thường xuyên hơn, và mỗi lần mở là một cơ hội bán thêm mà không phải kéo khách mới. Mặt trái: tần suất cao thường đi với biên mỏng. Dịch vụ kề như giao đồ ăn có thể cần trợ giá và hoa hồng, nên mở app nhiều hơn chưa chắc lãi trên mỗi khách cao hơn. Nguyên lý: tận dụng thứ đã có để phục vụ nhu cầu gần kề, nhưng phải tính lãi từng dịch vụ.' },
  example:'Giả sử (số minh hoạ) một người dùng gọi xe 2 lần/tuần. Khi ứng dụng có thêm đặt đồ ăn, họ đặt thêm 3 bữa/tuần: số lần mở tăng từ 2 lên 5, gấp 2,5 lần, và chi phí có khách chỉ bỏ ra một lần. Nhưng nếu mỗi chuyến xe lãi 6.000đ còn mỗi đơn đồ ăn sau trợ giá chỉ lãi 1.000đ, lãi tuần từ 2 × 6.000 = 12.000đ lên 12.000 + 3 × 1.000 = 15.000đ, tăng 25% trong khi số lần mở tăng 150%. Mở rộng đúng khi cả tần suất lẫn lãi trên mỗi khách cùng tăng.',
  takeaway:'Mở rộng khôn ngoan là phục vụ nhu cầu kề của khách sẵn có, dựa trên tài sản đã có.',
  apply:'Chọn một ứng dụng bạn dùng hằng ngày. Trong 60 giây, đề xuất một dịch vụ kề nó có thể thêm và giải thích tài sản sẵn có nào giúp làm được.',
  mistakes:['Thêm dịch vụ chỉ vì đối thủ có, không xét nhu cầu kề và tài sản sẵn có.','Coi tăng số dịch vụ là mục tiêu, quên đo số lần khách quay lại.'],
  q:[
  { type:'mcq', stem:'Đoán trước: lợi ích lớn nhất khi thêm đặt đồ ăn vào ứng dụng gọi xe là gì?',
    options:[{k:'a',t:'Ứng dụng trông hiện đại, nhiều tính năng hơn, nên dễ được các chuyên trang công nghệ khen ngợi'},{k:'b',t:'Được miễn chi phí quảng cáo cho dịch vụ mới'},
             {k:'c',t:'Tài xế không cần chạy xe chở khách nữa'},{k:'d',t:'Khách sẵn có dùng ứng dụng thường xuyên hơn mà không phải kéo khách mới từ đầu'}],
    answer:'d', why:{a:'Nhiều tính năng tự nó không tạo giá trị.',
      b:'Vẫn tốn chi phí quảng bá, chỉ là rẻ hơn khi khách đã có sẵn.',
      c:'Tài xế thường làm cả hai; không thay thế nhau.',
      d:'Đúng. Tần suất dùng tăng trên cùng tệp khách là lợi thế cốt lõi.'} },
  { type:'mcq', stem:'Bạn là brand manager một ứng dụng gọi xe nhỏ, được đề xuất thêm một trong bốn dịch vụ. Bạn chọn dịch vụ nào?',
    options:[{k:'a',t:'Giao hàng nội thành, tận dụng đúng đội tài xế và tài khoản khách đang có'},{k:'b',t:'Bán bảo hiểm xe máy theo năm ngay trong ứng dụng vì mỗi hợp đồng mang về khoản phí lớn'},
             {k:'c',t:'Đặt tour du lịch nước ngoài trọn gói cao cấp'},{k:'d',t:'Mở mạng xã hội chia sẻ ảnh cho người dùng'}],
    answer:'a', why:{a:'Đúng. Nhu cầu kề, dùng tài sản sẵn có (tài xế, khách), tần suất cao.',
      b:'Gần hơn bảo hiểm nhân thọ nhưng chỉ mua mỗi năm một lần, tần suất rất thấp và không dùng đội tài xế.',
      c:'Không dùng được đội tài xế; lĩnh vực mới hoàn toàn.',
      d:'Không liên quan năng lực lõi; cạnh tranh với các nền tảng rất lớn.'} },
  { type:'calc', stem:'Giả sử một khách gọi xe 2 lần/tuần. Sau khi có đặt đồ ăn, họ đặt thêm 4 bữa/tuần. Số lần dùng ứng dụng tăng bao nhiêu phần trăm?',
    unit:'%', ans:200, tol:0.5, wrong:[[300,'SAI_MAU_SO'],[66.7,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Trước: 2 lần. Sau: 2 + 4 = 6 lần.','Mức tăng = (6 − 2) ÷ 2 = 2 = <b>200%</b>.','Lấy 6 ÷ 2 = 300% là nhầm "gấp 3 lần" với "tăng 300%".'] },
  { type:'calc', stem:'Giả sử (số minh hoạ) khách gọi xe 2 lần/tuần, lãi 6.000đ mỗi chuyến. Họ đặt thêm 3 đơn đồ ăn mỗi tuần, mỗi đơn lãi gộp 4.000đ nhưng ứng dụng trợ giá 5.000đ cho khách ở mỗi đơn. Tổng lãi mỗi tuần từ khách này là bao nhiêu đồng?',
    unit:'đồng', ans:9000, tol:0.5, wrong:[[24000,'QUEN_CHI_PHI_KHUYEN_MAI'],[12000,'SAI_TINH_TOAN']], errors:['QUEN_CHI_PHI_KHUYEN_MAI'],
    steps:['Lãi từ xe = 2 × 6.000 = 12.000đ.','Mỗi đơn đồ ăn: 4.000 − 5.000 = −1.000đ, nên 3 đơn = −3.000đ.','Tổng = 12.000 − 3.000 = <b>9.000đ</b>: số lần dùng tăng 150% nhưng lãi giảm.','Bỏ trợ giá ra 24.000đ; chỉ tính xe ra 12.000đ.'] },
  { type:'mcq', stem:'Tình huống mới: một chuỗi siêu thị có ứng dụng tích điểm ít người mở. Bài học siêu ứng dụng gợi ý hướng nào?',
    options:[{k:'a',t:'Thêm trò chơi điện tử để người dùng giải trí'},{k:'b',t:'Thêm đặt hàng giao tận nhà trong ngày từ chính siêu thị gần khách'},
             {k:'c',t:'Tăng số điểm thưởng lên gấp mười lần để khách có lý do mở ứng dụng mỗi ngày'},{k:'d',t:'Gửi thông báo mỗi giờ để khách nhớ mở ứng dụng'}],
    answer:'b', why:{a:'Trò chơi không kề nhu cầu mua sắm và không dùng tài sản sẵn có.',
      b:'Đúng. Nhu cầu kề (mua đồ hằng ngày), tận dụng cửa hàng và khách đã có.',
      c:'Tăng điểm tốn kém mà không tạo lý do dùng thường xuyên.',
      d:'Thông báo dày đặc gây phiền, khách dễ gỡ ứng dụng.'} },
  { type:'mcq', stem:'Chỉ số nào phản ánh đúng nhất việc chiến lược siêu ứng dụng đang hiệu quả?',
    options:[{k:'a',t:'Số dịch vụ trong ứng dụng tăng từ 3 lên 10 chỉ trong vòng một năm triển khai'},{k:'b',t:'Số lượt tải ứng dụng trong tháng đầu'},
             {k:'c',t:'Số lượt thích trên trang mạng xã hội'},{k:'d',t:'Tỉ lệ khách dùng từ hai dịch vụ trở lên và số lần mở mỗi tuần'}],
    answer:'d', why:{a:'Số dịch vụ là đầu vào, không phải kết quả.',
      b:'Lượt tải đo khách mới, không đo việc khách cũ dùng thêm.',
      c:'Lượt thích không liên quan hành vi dùng dịch vụ.',
      d:'Đúng. Đo đúng điều nguyên lý hứa: dùng nhiều dịch vụ, mở thường xuyên hơn.'} },
  { type:'mcq', stem:'Bạn thực tập hỏi: "Sao không làm mỗi thứ một ứng dụng?" Câu trả lời nào đúng nhất?',
    options:[{k:'a',t:'Vì gộp một ứng dụng thì rẻ hơn hẳn: một đội lập trình, một máy chủ và một lần xin duyệt lên kho'},{k:'b',t:'Vì làm riêng thì mỗi ứng dụng phải kéo khách lại từ đầu; gộp lại dùng chung khách và thói quen'},
             {k:'c',t:'Vì kho ứng dụng không cho một công ty có nhiều ứng dụng'},{k:'d',t:'Vì người dùng thích ứng dụng thật nặng, nhiều nút'}],
    answer:'b', why:{a:'Chi phí kỹ thuật chỉ là phần nhỏ; lý do chính nằm ở khách hàng.',
      b:'Đúng. Tài sản lớn nhất là khách đã có và thói quen mở ứng dụng.',
      c:'Không đúng; nhiều công ty có nhiều ứng dụng.',
      d:'Ngược lại; ứng dụng nặng là điểm trừ cần quản lý.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:in02-08', skill:'insight', read:'6 phút', t:'Bánh trung thu Kido: người mua có phải người ăn?',
  situation:'Mỗi mùa Trung thu, các quầy bánh của Kido và nhiều hãng khác mọc lên dọc phố, bày những hộp bánh in hoa văn, có quai xách. Phần lớn hộp được mua để biếu đối tác, người thân, thầy cô. Người mua cầm hộp, xem bao bì, hỏi giá — ít khi nếm thử. Bạn được giao phân tích: ai là khách hàng thật của hộp bánh?',
  concept:{ name:'Người mua, người duyệt, người ăn và dịp mua',
    body:'Với quà biếu, <b>người mua</b> và <b>người ăn</b> thường khác nhau; với đơn doanh nghiệp còn thêm <b>người duyệt</b>. Mỗi người lo một thứ: người mua lo hộp tươm tất, giao đúng hạn, có hoá đơn; người duyệt lo giá nằm trong ngân sách quà và thương hiệu đủ quen để không phải giải thích; người ăn lo vị bánh. Quảng cáo chỉ nói về vị là nói với người ít quyết định nhất. Sản phẩm mùa vụ như bánh trung thu còn gắn với <b>dịp</b>: bán trong vài tuần, nên có mặt đúng lúc quan trọng không kém chất lượng.' },
  example:'Giả sử (minh hoạ) phòng hành chính một công ty mua 40 hộp bánh biếu đối tác, mỗi hộp 550.000đ, tổng 22 triệu. Nhân viên hành chính là người mua: lo giao đúng hạn, có hoá đơn. Trưởng phòng là người duyệt: lo giá nằm trong ngân sách quà và thương hiệu quen để khỏi bị hỏi. Đối tác nhận hộp mới là người ăn. Một thông điệp "nhân thơm ngon" chỉ chạm người cuối cùng. Hãng cần ba thông điệp riêng: giao hẹn và hoá đơn cho người mua, mức giá theo hạng quà cho người duyệt, vị bánh cho người ăn.',
  takeaway:'Với quà biếu, hãy nói với người mua điều họ lo, không chỉ nói với người ăn điều họ thích.',
  apply:'Nghĩ về một món quà bạn từng mua biếu. Trong 60 giây, nói: bạn chọn dựa trên gì, và người nhận quan tâm điều gì.',
  mistakes:['Chỉ quảng cáo hương vị khi người quyết định mua là người không ăn.','Chuẩn bị muộn cho sản phẩm mùa vụ, lỡ đúng giai đoạn khách chọn mua.'],
  q:[
  { type:'mcq', stem:'Đoán trước: khi chọn hộp bánh trung thu để biếu sếp, người mua thường quan tâm điều gì nhất?',
    options:[{k:'a',t:'Thành phần dinh dưỡng chi tiết của từng loại nhân'},{k:'b',t:'Nguồn gốc xuất xứ của hạt sen trong nhân'},
             {k:'c',t:'Thương hiệu quen, hộp tươm tất, giá hợp với mối quan hệ'},{k:'d',t:'Bánh có ít đường hay không'}],
    answer:'c', why:{a:'Người mua để biếu ít khi xem kỹ dinh dưỡng.',
      b:'Chi tiết nguyên liệu quan trọng với người ăn kỹ tính, không phải mối lo chính của người biếu.',
      c:'Đúng. Món quà phải "đúng mực" với người nhận — đó là nỗi lo của người mua.',
      d:'Ít đường có thể là điểm cộng, nhưng không phải tiêu chí chính khi mua biếu.'} },
  { type:'mcq', stem:'Bạn là brand manager một hãng bánh trung thu. Bạn chọn thông điệp chính cho khách doanh nghiệp là gì?',
    options:[{k:'a',t:'"Nhân bánh thơm ngon, công thức truyền thống lâu đời"'},{k:'b',t:'"Hộp quà trang trọng, giao đúng hẹn, xuất hoá đơn đầy đủ"'},
             {k:'c',t:'"Giảm giá 50% cho khách mua lẻ tại quầy"'},{k:'d',t:'"Bánh ít calo, phù hợp người ăn kiêng"'}],
    answer:'b', why:{a:'Nói với người ăn; người mua doanh nghiệp cần được trấn an về khâu khác.',
      b:'Đúng. Trả lời đúng nỗi lo của người ra quyết định mua.',
      c:'Giảm giá mua lẻ không chạm tới khách doanh nghiệp, còn làm hộp quà "kém sang".',
      d:'Ăn kiêng là nhóm nhỏ, không phải mối quan tâm của người mua biếu số lượng lớn.'} },
  { type:'calc', stem:'Hai báo giá cho 40 hộp bánh. Hãng A: 550.000đ/hộp, chiết khấu 10% trên tổng đơn, đã gồm giao. Hãng B: 520.000đ/hộp, không chiết khấu, phí giao 1,5 triệu cho cả đơn. Hãng rẻ hơn rẻ hơn bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:2.5, tol:0.01, wrong:[[1,'SAI_TINH_TOAN'],[0.3,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Hãng A: 40 × 550.000 = 22.000.000đ; sau chiết khấu 10% = <b>19,8 triệu</b>.','Hãng B: 40 × 520.000 = 20,8 triệu; cộng phí giao 1,5 triệu = 22,3 triệu.','Chênh lệch = 22,3 − 19,8 = <b>2,5 triệu đồng</b> (A rẻ hơn).','Bỏ phí giao ra 1,0 triệu; quên chiết khấu của A ra 0,3 triệu.'] },
  { type:'mcq', stem:'Giả sử nhiều đơn doanh nghiệp được đặt trước vài tuần. Vì sao sản phẩm mùa vụ như bánh trung thu cần chuẩn bị kênh bán từ rất sớm?',
    options:[{k:'a',t:'Vì bánh càng để lâu càng ngon hơn'},{k:'b',t:'Vì khách chỉ đổ đi mua vào đúng ngày rằm tháng Tám, nên phải có hàng sẵn thật nhiều từ trước đó'},
             {k:'c',t:'Vì đối thủ thường giảm giá ngay từ đầu mùa'},{k:'d',t:'Vì mùa bán ngắn; lỡ vài tuần đầu là lỡ phần lớn đơn biếu doanh nghiệp đặt sớm'}],
    answer:'d', why:{a:'Bánh có hạn dùng; để lâu không làm ngon hơn.',
      b:'Ngược lại, theo dữ kiện đề bài nhiều đơn được đặt trước vài tuần, không dồn vào đúng ngày rằm.',
      c:'Không có căn cứ chung; không phải lý do chính.',
      d:'Đúng. Sản phẩm theo dịp thì thời điểm có mặt quyết định doanh số.'} },
  { type:'mcq', stem:'Bạn là sales của hãng bánh. Một đơn 40 hộp bị trưởng phòng hành chính từ chối, dù nhân viên đặt hàng rất thích mẫu hộp. Bước đầu tiên nên làm là gì?',
    options:[{k:'a',t:'Hỏi để biết người duyệt lo điều gì: ngân sách, thương hiệu hay thời hạn giao'},{k:'b',t:'Giảm giá thêm 20% để người duyệt dễ gật đầu hơn'},
             {k:'c',t:'Gửi thêm hộp bánh dùng thử cho nhân viên đặt hàng'},{k:'d',t:'Đổi thông điệp sang nhấn mạnh hương vị và công thức truyền thống'}],
    answer:'a', why:{a:'Đúng. Người duyệt có mối lo riêng khác người mua; chưa biết lo gì thì mọi chỉnh sửa khác chỉ là đoán.',
      b:'Giảm giá chỉ đúng nếu mối lo là ngân sách; nếu là thương hiệu hay thời hạn giao thì mất biên mà không đổi kết quả.',
      c:'Nhân viên đặt hàng đã thích rồi; người từ chối là người khác.',
      d:'Hương vị là mối quan tâm của người ăn, không phải của người duyệt đơn.'} },
  { type:'mcq', stem:'Điều nào cho thấy bao bì hộp bánh có vai trò marketing, không chỉ là vỏ bọc?',
    options:[{k:'a',t:'Hộp làm tăng trọng lượng khi vận chuyển'},{k:'b',t:'Hộp càng to và càng nặng tay thì người mua càng tin bánh bên trong ngon hơn'},
             {k:'c',t:'Hộp chỉ để bảo vệ bánh khỏi bị vỡ'},{k:'d',t:'Người mua đánh giá món quà qua chiếc hộp trước khi người nhận ăn bánh'}],
    answer:'d', why:{a:'Trọng lượng là chi phí, không phải vai trò marketing.',
      b:'Kích thước hộp không liên quan vị bánh.',
      c:'Bảo vệ là chức năng cơ bản; câu hỏi là vai trò marketing.',
      d:'Đúng. Với quà biếu, hộp là phần đầu tiên của trải nghiệm và thể hiện sự tôn trọng.'} },
  { type:'mcq', stem:'Nhận định nào về case bánh trung thu là phân tích công bằng, không bịa số?',
    options:[{k:'a',t:'"Kido bán đúng 3 triệu hộp mỗi năm."'},{k:'b',t:'"Bánh trung thu là sản phẩm theo dịp, nhiều hộp được mua để biếu."'},
             {k:'c',t:'"Hầu như ai mua bánh trung thu cũng chỉ để biếu, gần như không ai mua để ăn."'},{k:'d',t:'"Bánh của Kido ngon nhất thị trường nên bán chạy."'}],
    answer:'b', why:{a:'Con số không có nguồn là bịa.',
      b:'Đúng. Điều quan sát được rộng rãi, đủ để rút nguyên lý.',
      c:'Khái quát quá mức; nhiều người mua cả để ăn.',
      d:'Khẳng định cảm tính, không kiểm chứng được.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:in02-09', skill:'brand', read:'7 phút', t:'Trung Nguyên bán cà phê hay bán một ý nghĩa?',
  situation:'Trung Nguyên là thương hiệu cà phê Việt lâu năm, gắn với khẩu hiệu về khơi nguồn sáng tạo và hình ảnh cà phê như năng lượng cho người làm việc, sáng tạo. Cùng tập đoàn còn có G7 — dòng cà phê hoà tan dễ pha, có mặt rộng ở siêu thị. Bạn được giao phân tích: hai dòng này đang nói với ai, trong dịp nào?',
  concept:{ name:'Ý nghĩa thương hiệu và danh mục theo dịp',
    body:'Có hai ý khác nhau. Một là <b>ý nghĩa thương hiệu</b>: gắn sản phẩm với điều lớn hơn công dụng, như "cà phê cho người sáng tạo", để khách thấy mình trong thương hiệu. Hai là <b>danh mục theo dịp</b>: cà phê pha phin cho lúc thong thả, hoà tan cho lúc vội, mỗi dòng một vai. Ý nghĩa thường nằm ở dòng gắn với hình ảnh thương hiệu; dòng tiện lợi bán bằng sự dễ mua và dễ pha. Giới hạn: ý nghĩa không thay được phân phối và giá. Một thương hiệu có ý nghĩa lớn vẫn mất khách nếu đối thủ phủ rộng hơn hoặc rẻ hơn.' },
  example:'Giả sử một người uống 10 ly cà phê/tuần: 3 ly pha phin cuối tuần, 7 ly hoà tan buổi sáng vội ở văn phòng. Nếu hãng chỉ có cà phê phin, hãng chỉ chạm 3 dịp. Có thêm dòng hoà tan, hãng chạm cả 10 dịp. Nhưng nếu hai dòng nói cùng một thông điệp, khách sẽ không hiểu nên chọn dòng nào lúc nào. Và dù ý nghĩa hay đến đâu, nếu đối thủ có gói hoà tan rẻ hơn và nằm ở mọi tạp hoá, người vội buổi sáng vẫn mua của đối thủ.',
  takeaway:'Ý nghĩa giúp khách gắn bó; danh mục theo dịp giúp thương hiệu có mặt ở nhiều khoảnh khắc hơn.',
  apply:'Chọn một thương hiệu có hai dòng sản phẩm. Trong 60 giây, nói: mỗi dòng phục vụ dịp nào, và chúng có giẫm chân nhau không.',
  mistakes:['Nghĩ thông điệp ý nghĩa là chữ đẹp, không cần gắn với hành vi thật của khách.','Cho mọi dòng sản phẩm nói cùng một điều, khách không biết chọn dòng nào.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao một thương hiệu cà phê gắn mình với "sáng tạo" thay vì chỉ nói "cà phê đậm"?',
    options:[{k:'a',t:'Để người uống thấy thương hiệu đồng hành với điều họ theo đuổi, không chỉ với vị cà phê'},{k:'b',t:'Vì luật yêu cầu quảng cáo không được nói về vị'},
             {k:'c',t:'Vì cà phê đậm là thứ khách không còn quan tâm, khi quán nào ngoài phố cũng bán cà phê đậm như nhau'},{k:'d',t:'Để bán được giá rẻ hơn đối thủ'}],
    answer:'a', why:{a:'Đúng. Ý nghĩa lớn hơn công dụng giúp khách gắn bó theo cách sản phẩm đơn thuần khó làm được.',
      b:'Không nên khẳng định luật cụ thể; đây cũng không phải lý do.',
      c:'Vị vẫn quan trọng; ý nghĩa là lớp bổ sung.',
      d:'Ý nghĩa thường giúp giữ giá, không phải giảm giá.'} },
  { type:'mcq', stem:'Bạn là brand manager, công ty có dòng cà phê phin và dòng hoà tan. Bạn chọn cách định vai trò nào?',
    options:[{k:'a',t:'Cho cả hai dòng dùng chung một thông điệp để tiết kiệm chi phí sáng tạo'},{k:'b',t:'Bỏ dòng hoà tan vì nó làm giảm hình ảnh cao cấp của cà phê phin'},
             {k:'c',t:'Mỗi dòng một dịp rõ: phin cho lúc thong thả, hoà tan cho buổi sáng vội'},{k:'d',t:'Giảm giá dòng phin xuống ngang hoà tan để khách chuyển sang'}],
    answer:'c', why:{a:'Chung thông điệp khiến khách không biết chọn dòng nào lúc nào.',
      b:'Bỏ hoà tan là bỏ lỡ nhiều dịp uống hằng ngày.',
      c:'Đúng. Vai trò theo dịp giúp hai dòng bổ sung thay vì ăn khách của nhau.',
      d:'Giảm giá dòng phin làm mờ khác biệt và mỏng lãi.'} },
  { type:'calc', stem:'Giả sử (số minh hoạ) một người uống 12 ly/tuần: 4 ly phin, 8 ly hoà tan của hãng khác. Hãng ra dòng hoà tan; 5 trong 8 ly hoà tan chuyển sang hãng, và 1 ly phin chuyển sang hoà tan của chính hãng. Lãi gộp: phin 8.000đ/ly, hoà tan 3.000đ/ly. Lãi mỗi tuần từ người này tăng thêm bao nhiêu đồng?',
    unit:'đồng', ans:10000, tol:0.5, wrong:[[15000,'SAI_TINH_TOAN'],[18000,'SAI_TINH_TOAN'],[42000,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Trước: 4 ly phin × 8.000 = 32.000đ.','Sau: phin còn 3 ly × 8.000 = 24.000đ; hoà tan của hãng 5 + 1 = 6 ly × 3.000 = 18.000đ; tổng 42.000đ.','Tăng thêm = 42.000 − 32.000 = <b>10.000đ</b>.','15.000 quên ly phin chuyển sang; 18.000 quên mất lãi phin; 42.000 là tổng chứ chưa trừ mức cũ.'] },
  { type:'mcq', stem:'Dấu hiệu nào cho thấy hai dòng sản phẩm đang "giẫm chân" nhau?',
    options:[{k:'a',t:'Hai dòng bán ở hai loại kênh khác nhau'},{k:'b',t:'Hai dòng có giá khác nhau đáng kể, khiến khách so sánh và băn khoăn không biết nên chọn dòng nào'},
             {k:'c',t:'Hai dòng dùng bao bì hai màu khác nhau'},{k:'d',t:'Khách chuyển từ dòng này sang dòng kia trong cùng một dịp, tổng lượng mua không tăng'}],
    answer:'d', why:{a:'Kênh khác thường là dấu hiệu phân vai tốt.',
      b:'Giá khác nhau không chứng minh giẫm chân.',
      c:'Màu bao bì khác không nói gì về hành vi mua.',
      d:'Đúng. Dòng mới chỉ lấy khách của dòng cũ thì công ty không lớn thêm.'} },
  { type:'mcq', stem:'Tình huống mới: một thương hiệu nước mắm muốn gắn với "bữa cơm gia đình". Điều gì giúp ý nghĩa này không thành khẩu hiệu rỗng?',
    options:[{k:'a',t:'Thể hiện qua hoạt động thật: công thức món nhà, cỡ chai theo số người, chuyện bữa tối'},{k:'b',t:'In khẩu hiệu thật to trên chai'},
             {k:'c',t:'Lặp khẩu hiệu "bữa cơm gia đình" thật nhiều lần trong một quảng cáo 15 giây để khách thuộc lòng'},{k:'d',t:'Đổi tên thương hiệu thành "Bữa Cơm"'}],
    answer:'a', why:{a:'Đúng. Ý nghĩa sống được khi nó hiện ra trong sản phẩm và hành vi thật.',
      b:'Chữ to không làm ý nghĩa thật hơn.',
      c:'Lặp khẩu hiệu mà không có bằng chứng thì khách không tin.',
      d:'Đổi tên rủi ro và không tự tạo ra ý nghĩa.'} },
  { type:'mcq', stem:'Bài học nào từ case này áp dụng được cho một thương hiệu trà?',
    options:[{k:'a',t:'Bắt chước khẩu hiệu "khơi nguồn sáng tạo" cho trà, vì khẩu hiệu đó đã được thị trường chứng minh'},{k:'b',t:'Chọn một ý nghĩa gắn với đời sống khách, và chia dòng sản phẩm theo dịp uống'},
             {k:'c',t:'Chuyển hẳn sang trà hoà tan vì tiện hơn'},{k:'d',t:'Tránh gắn ý nghĩa, chỉ nói về vị để an toàn'}],
    answer:'b', why:{a:'Chép khẩu hiệu người khác khiến khách nhớ tới họ.',
      b:'Đúng. Học nguyên lý, không chép bề mặt.',
      c:'Bỏ các dịp thong thả là thu hẹp thị trường.',
      d:'Chỉ nói vị thì dễ bị so sánh thuần tuý với đối thủ.'} },
  { type:'mcq', stem:'Khi viết case Trung Nguyên cho lớp học, câu nào cần tránh?',
    options:[{k:'a',t:'Nêu khẩu hiệu và hình ảnh thương hiệu đã công khai trên bao bì và quảng cáo'},{k:'b',t:'Phân tích vai trò của hai dòng sản phẩm theo từng dịp uống cà phê'},
             {k:'c',t:'Viết "G7 chiếm hơn nửa thị phần hoà tan" vì nghe nhiều người nói vậy'},{k:'d',t:'Đặt câu hỏi "nếu bạn là brand manager" cho người học trả lời'}],
    answer:'c', why:{a:'Thông tin công khai, dùng được.',
      b:'Đây là phân tích hợp lệ.',
      c:'Đúng. Con số nghe quen mà không có nguồn vẫn là bịa số; phải dẫn nguồn hoặc không viết.',
      d:'Đây là cách học case hiệu quả.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:in02-10', skill:'insight', read:'7 phút', t:'Shopee ngày đôi: tạo ra dịp mua sắm từ con số?',
  situation:'Các ngày 9.9, 10.10, 11.11, 12.12 đã trở thành những "ngày hội mua sắm" quen thuộc trên Shopee và các sàn khác. Trước ngày đó vài tuần, ứng dụng nhắc liên tục, có đếm ngược, mã giảm giá, chương trình giải trí. Nhiều người để dành đồ trong giỏ chờ đúng ngày. Sếp hỏi: "Mình là một shop nhỏ trên sàn, học được gì từ đây?"',
  concept:{ name:'Tạo dịp mua và gom nhu cầu vào một khung giờ',
    body:'Một ngày không có ý nghĩa đặc biệt có thể được <b>biến thành dịp</b> khi lặp lại đều đặn, dễ nhớ (ngày trùng tháng), và có lời hứa rõ ràng (giảm giá, quà). Khách học được thói quen chờ đợi, gom nhu cầu vào đúng ngày. Với nhà bán, đó là cơ hội bán nhiều trong thời gian ngắn — nhưng cũng là cuộc đua giảm giá. Phải tính kỹ: đơn tăng có bù được phần giảm giá và chi phí không.' },
  example:'Giả sử một shop thường bán 40 đơn/ngày, lãi 30.000đ/đơn. Ngày đôi, shop giảm thêm 20.000đ/đơn và bán được 150 đơn. Lãi ngày thường: 40 × 30.000 = 1,2 triệu. Lãi ngày đôi: 150 × 10.000 = 1,5 triệu. Có lời hơn, nhưng nếu một phần đơn là của khách vốn định mua tuần trước, phần tăng thật nhỏ hơn con số trông thấy.',
  takeaway:'Ngày hội gom nhu cầu, không phải lúc nào cũng tạo thêm nhu cầu — hãy tính lãi, không chỉ đếm đơn.',
  points:["Ngày trùng tháng dễ nhớ vì không cần tra lịch. Một thói quen chỉ hình thành khi khách không phải nỗ lực để nhớ, và cấu trúc đơn giản như 11.11 làm phần việc đó.","Lặp lại đều đặn dạy khách rằng chờ thì sẽ có lời. Sau vài lần, họ chủ động để đồ trong giỏ, và nhu cầu bị dồn lại thay vì rải đều theo tuần.","Lời hứa cụ thể như giảm giá hay quà là cái neo cho việc chờ. Thiếu nó, ngày đôi chỉ là con số trên lịch và khách không có lý do đổi thói quen mua."],
  counter:"Tham gia ngày đôi sẽ sai khi lãi mỗi đơn đã mỏng. Giả sử shop chỉ lãi 30.000 đồng mỗi đơn mà giảm thêm 20.000 đồng, trong khi nhiều đơn là khách cũ dời ngày mua. Khi đó số đơn tăng trông đẹp mà lãi tăng thêm rất nhỏ. Dấu hiệu nhận ra là tỉ lệ khách cũ cao trong đơn ngày đôi và doanh thu tuần sau tụt. Lúc ấy nên thu nhỏ quy mô ưu đãi.",
  deeper:"Người làm nghề nhìn ngày đôi như một khoản vay từ tương lai: một phần doanh số hôm nay là doanh số của tuần trước bị dời sang. Đánh đổi là tham gia thì cuốn vào cuộc đua giá, bỏ qua thì mất mặt trong ngày khách tìm kiếm nhiều. Tín hiệu nên theo dõi là tỉ lệ khách mới so với khách cũ trong đơn, và doanh thu của tuần trước cùng tuần sau ngày đôi. Khái niệm kề cận là giá trị vòng đời của khách. Phép kiểm tra trong tuần: lấy số đơn hai tuần quanh ngày đôi gần nhất, so với hai tuần bình thường, xem tuần sau có lõm xuống không.",
  apply:'Nghĩ về lần bạn chờ ngày đôi để mua. Trong 60 giây, nói: nếu không có ngày đó, bạn có mua món ấy không, và mua lúc nào.',
  mistakes:['Chỉ nhìn số đơn tăng vọt, quên trừ phần giảm giá và chi phí.','Quên rằng nhiều khách chỉ dời ngày mua, không mua thêm.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao các ngày như 11.11 dễ trở thành thói quen mua sắm?',
    options:[{k:'a',t:'Vì đó là ngày lễ chính thức được nghỉ làm'},{k:'b',t:'Vì hàng hoá ngày đó được sản xuất riêng, tốt hơn'},
             {k:'c',t:'Vì ngày dễ nhớ, lặp lại mỗi tháng/năm, và có lời hứa giảm giá rõ ràng'},{k:'d',t:'Vì phí vận chuyển ngày đó được miễn, nên khách dồn đơn chờ đến đúng ngày'}],
    answer:'c', why:{a:'Đây không phải ngày nghỉ lễ.',
      b:'Hàng vẫn là hàng thường ngày; lý do là dịp và ưu đãi.',
      c:'Đúng. Dễ nhớ + lặp lại + lời hứa rõ = dịp mua sắm được học thuộc.',
      d:'Miễn phí vận chuyển có thể có, nhưng không giải thích vì sao thành thói quen; cốt lõi là ngày dễ nhớ, lặp lại, lời hứa rõ.'} },
  { type:'mcq', stem:'Bạn là brand manager một shop mỹ phẩm nhỏ trên sàn. Trước ngày 12.12, bạn chọn làm gì?',
    options:[{k:'a',t:'Giảm giá sâu nhất có thể cho các sản phẩm trong gian hàng để lọt top bán chạy và được sàn đẩy lên'},{k:'b',t:'Bỏ qua ngày đôi vì sợ cạnh tranh với các thương hiệu lớn trên sàn'},
             {k:'c',t:'Tăng giá gốc trước rồi giảm giá lại để trông như giảm sâu'},{k:'d',t:'Tính lãi từng mức giảm, chọn vài sản phẩm chủ lực và nhắc khách cũ lưu giỏ trước'}],
    answer:'d', why:{a:'Giảm sâu đồng loạt có thể bán nhiều mà lỗ.',
      b:'Bỏ hẳn là bỏ lỡ dịp khách đang chủ động tìm mua.',
      c:'Làm vậy làm mất lòng tin của khách, và có thể vi phạm quy định của sàn.',
      d:'Đúng. Tham gia có tính toán, tập trung vào nơi có lãi.'} },
  { type:'calc', stem:'Giả sử shop thường bán 50 đơn/ngày, lãi 40.000đ/đơn. Ngày đôi giảm thêm 25.000đ/đơn, bán 160 đơn. Lãi ngày đôi hơn ngày thường bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:0.4, tol:0.01, wrong:[[4.4,'QUEN_CHI_PHI_KHUYEN_MAI'],[6.4,'QUEN_CHI_PHI_KHUYEN_MAI']], errors:['QUEN_CHI_PHI_KHUYEN_MAI'],
    steps:['Lãi ngày thường = 50 × 40.000 = 2.000.000đ.','Lãi mỗi đơn ngày đôi = 40.000 − 25.000 = 15.000đ → 160 × 15.000 = 2.400.000đ.','Chênh lệch = 2,4 − 2,0 = <b>0,4 triệu đồng</b>.'] },
  { type:'mcq', stem:'Nếu 60 trong 160 đơn ngày đôi là khách vốn định mua trong tuần với giá thường, điều gì đúng?',
    options:[{k:'a',t:'Phần lãi tăng thật thấp hơn con số trông thấy, vì một phần đơn chỉ là dời ngày'},{k:'b',t:'Không sao, vì đơn nào cũng là đơn'},
             {k:'c',t:'Lãi tăng gấp đôi, vì khách quen vốn tin shop nên sẽ mua nhiều món hơn hẳn khi thấy giảm giá'},{k:'d',t:'Shop nên từ chối đơn của khách quen trong ngày đôi'}],
    answer:'a', why:{a:'Đúng. Khách dời ngày mua mà được giảm giá thì shop mất phần giảm trên những đơn vốn có.',
      b:'Đơn dời ngày làm giảm lãi của những ngày khác.',
      c:'Khách quen không tạo thêm lãi; họ mua rẻ hơn thường.',
      d:'Từ chối khách là vô lý; điều cần là tính đúng khi đánh giá chương trình.'} },
  { type:'mcq', stem:'Tình huống mới: một chuỗi nhà sách muốn tạo "ngày hội" riêng. Thiết kế nào khớp nguyên lý nhất?',
    options:[{k:'a',t:'Giảm giá ngẫu hứng mỗi khi hàng tồn nhiều, không báo trước'},{k:'b',t:'Chọn một ngày dễ nhớ mỗi tháng, lặp lại đều, có lời hứa rõ và nhắc trước'},
             {k:'c',t:'Giảm giá quanh năm ở các đầu sách để khách ghé ngày thường vẫn thấy rẻ, không cần chờ dịp'},{k:'d',t:'Tổ chức một lần thật hoành tráng vào dịp khai trương'}],
    answer:'b', why:{a:'Không báo trước, không lặp lại thì khách không học được thói quen chờ.',
      b:'Đúng. Dễ nhớ, đều đặn, lời hứa rõ — ba yếu tố tạo ra dịp.',
      c:'Giảm quanh năm thì không còn "dịp", khách không có lý do đến vào ngày cụ thể.',
      d:'Một lần thì không thành thói quen.'} },
  { type:'mcq', stem:'Chỉ số nào giúp shop đánh giá đúng hiệu quả ngày đôi?',
    options:[{k:'a',t:'Số đơn trong ngày đôi so với số đơn trung bình của một ngày thường trước đó'},{k:'b',t:'Lượt xem gian hàng trong ngày đôi'},
             {k:'c',t:'Số người theo dõi shop tăng trong ngày'},{k:'d',t:'Lãi cả hai tuần quanh ngày đôi so với hai tuần bình thường'}],
    answer:'d', why:{a:'Số đơn không tính giảm giá và việc khách dời ngày.',
      b:'Lượt xem không phải lãi.',
      c:'Người theo dõi có ích lâu dài nhưng không đo hiệu quả tài chính của dịp.',
      d:'Đúng. Nhìn khung rộng hơn bắt được cả phần đơn bị dời ngày và phần giảm giá.'} },
  { type:'mcq', stem:'Nguyên lý lớn nhất rút ra từ case ngày đôi của Shopee là gì?',
    options:[{k:'a',t:'Có thể tạo ra dịp mua bằng sự lặp lại đều đặn và lời hứa rõ, nhưng phải đo lãi thật'},{k:'b',t:'Cứ giảm giá càng sâu càng thắng lớn, vì trong ngày đôi khách chỉ nhìn con số phần trăm giảm'},
             {k:'c',t:'Chỉ sàn lớn mới được tổ chức ngày hội mua sắm'},{k:'d',t:'Ngày hội là cách hiệu quả nhất để bán hàng online'}],
    answer:'a', why:{a:'Đúng. Gồm cả cơ chế tạo dịp và lưu ý tài chính.',
      b:'Giảm sâu có thể bán nhiều mà lỗ.',
      c:'Thương hiệu nhỏ cũng có thể tạo dịp riêng cho khách của mình.',
      d:'Không có căn cứ so sánh; ngày hội là một công cụ, và còn phải đo lãi thật.'} }
  ] }

]});
